-- Atualização da agenda (skill bayle-atualizacao) em 18/11/2026: festas futuras da intermediação e line-ups avaliáveis no /ranking.
-- Nunca apaga festa do banco (apagar levaria junto os anúncios de ingresso); festa vencida só sai do site pelo arquivo.
begin;
on conflict(id) do update set event_date=excluded.event_date,venue=excluded.venue,title=excluded.title;
on conflict(id) do update set title=excluded.title,source=excluded.source,
 lineup=case when brb_private.event_catalog.event_date>current_date then excluded.lineup
  else (select coalesce(jsonb_agg(distinct v.value),'[]'::jsonb) from jsonb_array_elements(brb_private.event_catalog.lineup||excluded.lineup) v) end;
commit;